        final double next = numerator / denominator;
        if (Double.isNaN(next)) {
            return value;
        }
        if (FastMath.abs(next - value) <= epsilon * FastMath.abs(next)) {
            return next;
        }
        value = next;
    }
    throw new MaxIterationsExceededException(maxIterations);
}


